targets.query:
from(bucket: "monitoring")
  |> range(start: -90d)
  |> filter(fn: (r) => r._measurement == "lonsemonsy_backup" and exists r.store and r.store == "local")
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")
  |> sort(columns: ["_time"])
  |> tail(n: 1)
  |> map(fn: (r) => {
      hours = (int(v: now()) - int(v: r._time)) / 3600000000000
      ago = if hours < 1 then "less than an hour ago" else if hours == 1 then "1 hour ago" else if hours < 48 then string(v: hours) + " hours ago" else string(v: hours / 24) + " days ago"
      state = if r.ok == 0 then "FAILED" else if hours > 36 then "LATE" else "OK"
      return {_time: r._time, n: if r.store == "cloud" then "2" else "1", where: if r.store == "cloud" then "Cloud" else "Local",
              _value: state + " · " + ago + " · " + string(v: r.copies) + " copies · " + string(v: r.size / 1048576) + " MB"}
  })
  |> group(columns: ["n", "where"])   // this server first

