// Goes through Grafana, which adds the button's token and your user name on the server.
return fetch('/api/datasources/proxy/uid/lons-backup-api/backup/local', { method: 'POST' })
  .then(function (r) {
    return r.json().catch(function () { return {}; }).then(function (body) {
      var msg = body.message || ('Error ' + r.status);
      if (r.ok) { context.grafana.notifySuccess(['Backup', msg]); }
      else if (r.status === 409) { context.grafana.notifyWarning(['Backup', msg]); }
      else { context.grafana.notifyError(['Backup', msg]); }
    });
  })
  .catch(function (e) { context.grafana.notifyError(['Backup', 'Could not reach the backup service (' + e.message + ')']); });

